import json
from pathlib import Path
def program(body,extra=''):return 'public class Main {\n'+extra+'\n  public static void main(String[] args) {\n'+body+'\n  }\n}'
rows=[
('java-1-1','    System.out.println("Hello!");','Hello!','برنامج Java الصغير يحتاج فئة Main ونقطة بداية main. نعرض رسالة لنعرف أن التنفيذ وصل للسطر المطلوب.','public class Main اسم الفئة، وmain نقطة الدخول. System.out.println يعرض النص ثم ينهي السطر. الأقواس المعقوفة تحدد جسم كل جزء.','توقع Hello! فقط دون الاقتباس أو اسم الأمر، ثم شغّل البرنامج.','غيّر النص وحده إلى اسمك، مع الحفاظ على تهجئة Main وmain.','Java حساسة لحالة الحروف؛ Main ليست main، والفاصلة المنقوطة تنهي أمر العرض.'),
('java-1-2','    System.out.print("Hello ");\n    System.out.println("Cody");\n    // This comment is not output','Hello Cody','تريد كتابة جزأين في السطر نفسه مع تعليق يوضح الكود للقارئ.','print لا ينهي السطر، بينما println ينهيه. لذلك الكلمتان تظهران معًا. // يجعل بقية السطر تعليقًا لا يظهر للمستخدم.','توقع سطرًا واحدًا Hello Cody. المسافة داخل النص الأول تفصل الكلمتين.','بدّل print الأولى إلى println لتلاحظ فصل الكلمتين إلى سطرين.','التعليق لا يُطبع؛ لا تضع // قبل أمر تريد تنفيذه.'),
('java-2-1','    int age = 16;\n    double price = 25.5;\n    String name = "Cody";\n    boolean active = true;\n    System.out.println(name);\n    System.out.println(age);\n    System.out.println(price);\n    System.out.println(active);','Cody\n16\n25.5\ntrue','بطاقة شخص تجمع اسمًا وعمرًا وسعرًا وحالة نشاط. لكل قيمة نوع يناسبها.','int للعدد الصحيح، double للعشري، String للنص وboolean للقيمة المنطقية. الطباعة تستخدم أسماء المتغيرات لتقرأ قيمها.','رتب القيم وفق أوامر الطباعة، لا ترتيب الإعلان فقط. ثم شغّل وقارن أربعة أسطر.','غيّر active إلى false فقط، ولا تضع اقتباسًا حولها.','String تبدأ بحرف كبير، وtrue قيمة منطقية وليست النص "true".'),
('java-2-2','    int score = 10;\n    score = score + 10;\n    System.out.println(score);','20','النقاط تتغير أثناء اللعب. نحتاج تحديث المتغير بدل إنشاء اسم جديد لكل مرحلة.','الإعلان الأول يحجز المتغير بقيمة10. الإسناد التالي يحسب القيمة القديمة +10 ثم يخزن20 داخل الاسم نفسه.','توقع20 قبل التشغيل. لا يوجد أمر طباعة قبل التحديث، لذلك10 لا تظهر.','غيّر الزيادة من10 إلى5 فقط، وتوقع15.','لا تعلن int score مرة ثانية في النطاق نفسه؛ بعد الإعلان يكفي استخدام الاسم للإسناد.'),
('java-3-1','    int a = 10, b = 3;\n    System.out.println(a + b);\n    System.out.println(a * b);\n    System.out.println(a / b);\n    System.out.println(a / 3.0);','13\n30\n3\n3.3333333333333335','الحساب يتغير حسب العملية والنوع. قسمة عددين صحيحين تختلف عن قسمة عشرية.','+ تجمع و* تضرب. a / b تستخدم int فتنتج3، أما a / 3.0 فتستخدم قسمة عشرية.','توقع الأسطر الأربعة؛ لاحظ أن الناتج العشري تقريب حاسوبي. شغّل وقارن.','غيّر a إلى12: تصبح القسمة4 في الحالتين، لكن العرض العشري يظهر4.0.','تخزين ناتج قسمة int في double لا يستعيد كسرًا حُذف بالفعل؛ غيّر نوع أحد طرفي القسمة.'),
('java-3-2','    System.out.println(10 % 3);\n    System.out.println(12 % 3);','1\n0','باقي القسمة يخبرنا هل يتوزع العدد بالتساوي. نستخدمه مثلًا لفحص الزوجي والفردي.','10 تحتوي ثلاث مجموعات من3 ويتبقى1. 12 تنقسم إلى أربع مجموعات دون باقٍ، فتنتج0.','توقع1 ثم0، وليس ناتج القسمة3 و4.','غيّر المثال الأول إلى10 % 2؛ توقع0، ثم فكر ماذا يعني ذلك عن زوجية10.','% باقي قسمة وليس نسبة مئوية، ولا يجوز استخدام مقسوم عليه صفر هنا.'),
('java-4-1','    int age = 18;\n    if (age >= 18) {\n      System.out.println("Adult");\n    }\n    System.out.println("Done");','Adult\nDone','رسالة تظهر عند بلوغ حد عمر معين، بينما يستمر البرنامج بعد الفحص.','if تقرأ القيمة المنطقية للمقارنة. الأقواس المعقوفة تحصر الرسالة المشروطة، وDone خارجها.','العمر18 يحقق >=18. توقع الرسالتين ثم شغّل.','غيّر العمر إلى17 فقط؛ توقع بقاء Done وحدها.','لا تضع ; بعد if (...) قبل الكتلة. == للمقارنة و= للإسناد.'),
('java-4-2','    int number = 5;\n    if (number > 0) {\n      System.out.println("Positive");\n    } else {\n      System.out.println("Not positive");\n    }','Positive','تريد ردًا سواء كان الرقم موجبًا أم لا. else تمثل الطريق البديل.','عند5 الشرط صحيح فينفذ Positive. عند0 أو رقم سالب يفشل الشرط، فينفذ Not positive.','توقع فرعًا واحدًا لا الاثنين، ثم شغّل.','غيّر number إلى0: هل الصفر موجب؟ توقع Not positive وتحقق.','else لا تعني سالب فقط هنا؛ هي تشمل الصفر لأن الشرط الأصلي >0.'),
('java-5-1','    for (int i = 1; i <= 3; i++) {\n      System.out.println(i);\n    }','1\n2\n3','العداد يكرر أمرًا منظمًا بدل نسخ السطر لكل عدد.','البداية مرة واحدة، والشرط قبل كل دورة، وi++ بعدها. عند4 يتوقف التكرار.','تتبع1 ثم2 ثم3، وتوقع ثلاثة أسطر قبل التشغيل.','بدّل <= إلى < فقط؛ توقع اختفاء3.','اختر الحدود بعناية؛ البداية0 مع <=3 تعطي أربع دورات لا ثلاثًا.'),
('java-5-2','    int count = 1;\n    while (count <= 3) {\n      System.out.println(count);\n      count++;\n    }','1\n2\n3','نكرر ما دام الشرط صحيحًا، ونحتاج تحديثًا يجعل الحلقة تنتهي.','count تبدأ1، ثم نطبع ونزيد. عندما تصل4 يفشل الشرط ولا تدخل دورة أخرى.','هل4 ستظهر؟ لا، لأن الفحص قبل الجسم. شغّل وقارن.','غيّر البداية إلى4 لتلاحظ أن الحلقة لا تنفذ أي دورة.','حذف count++ يجعل الحلقة غير منتهية في المثال؛ لا تجربه على حسابك.'),
('java-6-1','    int[] numbers = {10, 20, 30};\n    System.out.println(numbers[0]);\n    System.out.println(numbers[2]);','10\n30','المصفوفة تحفظ درجات مرتبة من النوع نفسه، ونصل لكل عنصر بفهرس.','int[] نوع مصفوفة أعداد صحيحة. أول فهرس0 وآخر فهرس2 عندما يكون العدد3.','ضع الفهارس فوق العناصر، ثم توقع10 و30 قبل التشغيل.','غيّر الفهرس الثاني إلى1؛ توقع20.','الوصول لفهرس3 هنا يسبب ArrayIndexOutOfBoundsException، فلا تخلط العدد بآخر فهرس.'),
('java-6-2','    int[] numbers = {10, 20, 30};\n    for (int i = 0; i < numbers.length; i++) {\n      System.out.println(numbers[i]);\n    }','10\n20\n30','تريد المرور على كل عنصر دون تثبيت آخر فهرس يدويًا. طول المصفوفة يحدد حد الحلقة.','numbers.length عدد العناصر. نبدأ0 ونستمر طالما i أصغر منه، فنصل للفهارس0 و1 و2 فقط.','توقع العناصر بالترتيب، ثم شغّل وعد الأسطر.','أضف40 داخل المصفوفة دون تعديل الحلقة. هل سيظهر تلقائيًا؟ جرب.','المصفوفة تستخدم length بلا أقواس. شرط <= length يحاول تجاوز الحدود.'),
('java-7-1','    greet();\n    greet();','Hello!\nHello!','التحية المتكررة تصبح Method نستدعيها بدل نسخها.','static تسمح باستدعاء greet من main الساكنة هنا. void تعني لا قيمة إرجاع. التعريف داخل Main وخارج main.','يوجد استدعاءان، فتوقع سطرين. التعريف وحده ليس تشغيلًا.','احذف استدعاءً واحدًا، واحتفظ بالتعريف.','الدالة العادية لا تُعرّف داخل main. الأقواس تحدد موضعها داخل الفئة.'),
('java-7-2','    int result = add(3, 4);\n    System.out.println(result);','7','مدخلان ونتيجة تجعل Method مفيدة في حسابات متعددة.','a وb معاملان من int. return تعيد المجموع للموضع الذي استدعى add، ثم نعرض result.','توقع7، وليس طباعة3 ثم4. شغّل لتتحقق.','غيّر الوسيط الثاني إلى9 فقط. توقع12.','الدالة ذات نوع int تحتاج return بقيمة مناسبة؛ println لا تحل محلها.'),
('java-8-1','    Student student = new Student();\n    System.out.println(student.name);','Ali','الفئة قالب لبيانات الطالب، والكائن نسخة فعلية يمكن أن تحمل بياناتها.','Student تعرّف الحقل name. new Student() تنشئ كائنًا، والمتغير student يشير إليه. النقطة تصل للحقل.','توقعAli من قيمة الحقل، ثم شغّل البرنامج الكامل.','أضف student.name = "Mona" قبل الطباعة. توقع تغير بيانات هذا الكائن.','Student اسم الفئة وstudent اسم متغير؛ حالة الحرف تميز الدورين في المثال.'),
('java-8-2','    Student student = new Student("Cody");\n    System.out.println(student.name);','Cody','نريد اختيار الاسم لحظة إنشاء الطالب بدل تعديل الحقل لاحقًا. المنشئ يهيئ الكائن.','Student(String studentName) منشئ يستقبل النص ويخزنه في name. new يستدعيه بالقيمة Cody.','توقعCody ثم شغّل. لاحظ أن الاستدعاء يمرر النص بين أقواس الإنشاء.','غيّر Cody في new فقط إلى اسم آخر، ثم تحقق من الطباعة.','المنشئ اسمه نفس الفئة ولا يكتب قبله void أو نوع إرجاع.')]
data={}
for id,body,out,scene,explain,predict,change,mistake in rows:
 extra=''
 if id=='java-7-1':extra='  public static void greet() { System.out.println("Hello!"); }'
 if id=='java-7-2':extra='  public static int add(int a, int b) { return a + b; }'
 code=program(body,extra)
 if id=='java-8-1':code='class Student { String name = "Ali"; }\n'+code
 if id=='java-8-2':code='class Student {\n  String name;\n  Student(String studentName) { name = studentName; }\n}\n'+code
 data[id]=dict(example=code,output=out,steps=[['الفكرة في موقف',scene],['نفك البرنامج معًا',explain],['توقّع ثم جرّب',predict],['غيّر شيئًا واحدًا',change]],mistake=mistake,recap='راجع توقعك مقابل المخرجات، ثم طبق الفكرة في مهمة الدرس قبل إكمال الاختبار.')
Path('/tmp/guided-java.json').write_text(json.dumps(data,ensure_ascii=False))
